<script lang="ts">import Upload,{type UploadFile,type UploadRejection} from './upload.svelte';let files=$state<UploadFile[]>([]);let added=$state(0),removed=$state(0),reasons=$state('');const onRejected=(r:UploadRejection[])=>reasons=r.map(x=>x.reason).join(',');</script><Upload bind:files accept="image/*" multiple maxSize={100} maxFiles={1} onFilesAdded={(items)=>added+=items.length} onFileRemoved={()=>removed++} {onRejected}/><output aria-label="file count">{files.length}</output><output aria-label="added count">{added}</output><output aria-label="removed count">{removed}</output><output aria-label="reasons">{reasons}</output>
